import{_ as a,o as e,c as s,a2 as d}from"./chunks/framework.Bg-Zxr5O.js";const p=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-en/Datasets.md","filePath":"manual-en/Datasets.md","lastUpdated":1785684581000}'),o={name:"manual-en/Datasets.md"};function r(n,t,i,l,c,m){return e(),s("div",null,[...t[0]||(t[0]=[d('<h3 id="_6-7-datasets" tabindex="-1">6.7 Datasets <a class="header-anchor" href="#_6-7-datasets" aria-label="Permalink to &quot;6.7 Datasets&quot;">​</a></h3><p>PSPP works with data organized into <em>datasets</em>. A dataset consists of a set of <em>variables</em> , which taken together are said to form a <em>dictionary</em> , and one or more <em>cases</em> , each of which has one value for each variable.</p><p>At any given time PSPP has exactly one distinguished dataset, called the <em>active dataset</em>. Most PSPP commands work only with the active dataset. In addition to the active dataset, PSPP also supports any number of additional open datasets. The <code>DATASET</code> commands can choose a new active dataset from among those that are open, as well as create and destroy datasets (see <a href="./DATASET">DATASET</a>).</p><p>The sections below describe variables in more detail.</p><table tabindex="0"><thead><tr><th>• Attributes</th><th></th><th>Attributes of variables.</th></tr></thead><tbody><tr><td>• System Variables</td><td></td><td>Variables automatically defined by PSPP .</td></tr><tr><td>• Sets of Variables</td><td></td><td>Lists of variable names.</td></tr><tr><td>• Input and Output Formats</td><td></td><td>Input and output formats.</td></tr><tr><td>• Scratch Variables</td><td></td><td>Variables deleted by procedures.</td></tr></tbody></table>',5)])])}const b=a(o,[["render",r]]);export{p as __pageData,b as default};
